configfiles.configfile:
suppressPackageStartupMessages(library(dupRadar))
args <- commandArgs(trailingOnly = TRUE) if (length(args) != 7) { stop("expected 7 arguments, got ", length(args)) } sample <- args[1] stranded <- as.integer(args[2]) paired <- as.logical(args[3]) feature_type <- args[4] attr_type <- args[5] plot_format <- args[6] multiqc <- args[7] == "true" threads <- as.integer(Sys.getenv("GALAXY_SLOTS", "1"))
dm <- analyzeDuprates( "input.bam", "annotation.gtf", stranded = stranded, paired = paired, threads = threads, GTF.featureType = feature_type, GTF.attrType = attr_type, verbose = TRUE ) write.table(dm, file = "dupMatrix.tsv", quote = FALSE, row.names = FALSE, sep = "\t") if (all(dm\$allCounts == 0)) { stop("No reads were assigned to any gene. Check that the GTF matches the reference (chromosome names) and that the strandedness and paired-end settings match the library.") }
## extension-less names so the outputs can switch format without changing from_work_dir open_plot <- function(name) { if (plot_format == "png") { png(name, width = 7, height = 7, units = "in", res = 150, type = "cairo") } else { pdf(name) } }
open_plot("duprateExpDens.plot") ## dupRadar's 0.5 RPKM marker errors out when no gene falls below it, e.g. with a small, ## well-covered annotation, so only draw it when it can be placed duprateExpDensPlot(DupMat = dm, tRPKM = any(dm\$RPKM <= 0.5, na.rm = TRUE)) title("Density scatter plot") mtext(sample, side = 3) invisible(dev.off())
open_plot("duprateExpBoxplot.plot") duprateExpBoxplot(DupMat = dm) title("Percent duplication by expression") mtext(sample, side = 3) invisible(dev.off())
open_plot("expressionHist.plot") expressionHist(DupMat = dm) title("Distribution of RPK values per gene") mtext(sample, side = 3) invisible(dev.off())
fit <- duprateExpFit(DupMat = dm) if (inherits(fit, "try-error")) { stop("dupRadar could not fit its duplication model to these data") } cat( paste("- dupRadar Int (duprate at low read counts):", fit\$intercept), paste("- dupRadar Sl (progression of the duplication rate):", fit\$slope), fill = TRUE, labels = sample, file = "intercept_slope.txt" )
if (multiqc) { writeLines(c( "#id: DupInt", "#plot_type: 'generalstats'", "#pconfig:", "# dupRadar_intercept:", "# title: 'dupInt'", "# namespace: 'DupRadar'", "# description: 'Intercept value from DupRadar'", "# max: 100", "# min: 0", "# scale: 'RdYlGn-rev'", "Sample\tdupRadar_intercept", paste(sample, fit\$intercept, sep = "\t") ), "dup_intercept_mqc.tsv")
## Sample the fitted GLM curve so MultiQC can draw it as a line graph curve_x <- sort(log10(dm\$RPK)) curve_x <- curve_x[is.finite(curve_x)] curve_y <- 100 * predict(fit\$glm, data.frame(x = curve_x), type = "response") ## every tenth point, and always the last one so the curve reaches the highest expression keep <- unique(c(seq(1, length(curve_x), 10), length(curve_x))) writeLines(c( "#id: dupradar", ## a two-column file carries no sample name, and MultiQC would otherwise take it from the file name paste0("#sample_name: '", sample, "'"), "#plot_type: 'linegraph'", "#section_name: 'DupRadar'", "#section_href: 'https://bioconductor.org/packages/release/bioc/html/dupRadar.html'", "#description: 'Duplication rate quality control for RNA-seq. This plot shows the general linear model fitted to the gene duplication rates.'", "#pconfig:", "# title: 'DupRadar General Linear Model'", "# xlog: True", "# xlab: 'expression (reads/kbp)'", "# ylab: '% duplicate reads'", "# ymax: 100", "# ymin: 0" ), "duprateExpDensCurve_mqc.tsv") write.table( cbind(10^curve_x[keep], curve_y[keep]), file = "duprateExpDensCurve_mqc.tsv", quote = FALSE, row.names = FALSE, col.names = FALSE, sep = "\t", append = TRUE ) }
